def push(node, l, r):
    if lz[node] != NONE:
        mid = (l + r) // 2
        apply(2*node, l, mid, lz[node]); apply(2*node + 1, mid + 1, r, lz[node])
        lz[node] = NONE

def assign(node, l, r, ql, qr, x):
    if ql <= l and r <= qr: apply(node, l, r, x); return      # the whole block is inside the range
    push(node, l, r)
    mid = (l + r) // 2
    if ql <= mid: assign(2*node, l, mid, ql, qr, x)
    if qr > mid: assign(2*node + 1, mid + 1, r, ql, qr, x)
    sm[node] = sm[2*node] + sm[2*node + 1]

